// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// AdminCreateOwner Create an owner with a password credential in a tenant (admin)
	// (POST /admin/owners)
	AdminCreateOwner(ctx context.Context, request AdminCreateOwnerRequestObject) (AdminCreateOwnerResponseObject, error)
	// AdminListTenants List all tenants (admin)
	// (GET /admin/tenants)
	AdminListTenants(ctx context.Context, request AdminListTenantsRequestObject) (AdminListTenantsResponseObject, error)
	// AdminCreateTenant Create a tenant (admin)
	// (POST /admin/tenants)
	AdminCreateTenant(ctx context.Context, request AdminCreateTenantRequestObject) (AdminCreateTenantResponseObject, error)
	// AdminListUsers List a tenant's users (admin)
	// (GET /admin/tenants/{tenantId}/users)
	AdminListUsers(ctx context.Context, request AdminListUsersRequestObject) (AdminListUsersResponseObject, error)
	// AdminCreateUser Create a user by email in a tenant (admin)
	// (POST /admin/tenants/{tenantId}/users)
	AdminCreateUser(ctx context.Context, request AdminCreateUserRequestObject) (AdminCreateUserResponseObject, error)
	// AdminUpdateUser Change a user's role or ban state (admin)
	// (PATCH /admin/tenants/{tenantId}/users/{userId})
	AdminUpdateUser(ctx context.Context, request AdminUpdateUserRequestObject) (AdminUpdateUserResponseObject, error)
	// Login Log in with a username and password
	// (POST /api/v1/auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// GetAuthMethods Owner login methods available on this host
	// (GET /api/v1/auth/methods)
	GetAuthMethods(ctx context.Context, request GetAuthMethodsRequestObject) (GetAuthMethodsResponseObject, error)
	// ConfirmPasswordReset Complete a password reset with a token
	// (POST /api/v1/auth/password-reset/confirm)
	ConfirmPasswordReset(ctx context.Context, request ConfirmPasswordResetRequestObject) (ConfirmPasswordResetResponseObject, error)
	// RequestPasswordReset Request a password-reset email
	// (POST /api/v1/auth/password-reset/request)
	RequestPasswordReset(ctx context.Context, request RequestPasswordResetRequestObject) (RequestPasswordResetResponseObject, error)
	// ListDomains List the tenant's custom domains
	// (GET /api/v1/domains)
	ListDomains(ctx context.Context, request ListDomainsRequestObject) (ListDomainsResponseObject, error)
	// AddDomain Add a custom domain (bring-your-own-domain)
	// (POST /api/v1/domains)
	AddDomain(ctx context.Context, request AddDomainRequestObject) (AddDomainResponseObject, error)
	// DeleteDomain Remove a custom domain
	// (DELETE /api/v1/domains/{domainId})
	DeleteDomain(ctx context.Context, request DeleteDomainRequestObject) (DeleteDomainResponseObject, error)
	// VerifyDomain Check the domain's DNS TXT verification record
	// (POST /api/v1/domains/{domainId}/verify)
	VerifyDomain(ctx context.Context, request VerifyDomainRequestObject) (VerifyDomainResponseObject, error)
	// PreviewItem Fetch item metadata from a product URL (browser auto-add)
	// (POST /api/v1/item-previews)
	PreviewItem(ctx context.Context, request PreviewItemRequestObject) (PreviewItemResponseObject, error)
	// DeleteItem Delete an item
	// (DELETE /api/v1/items/{itemId})
	DeleteItem(ctx context.Context, request DeleteItemRequestObject) (DeleteItemResponseObject, error)
	// UpdateItem Update an item
	// (PATCH /api/v1/items/{itemId})
	UpdateItem(ctx context.Context, request UpdateItemRequestObject) (UpdateItemResponseObject, error)
	// ListLists List the owner's lists
	// (GET /api/v1/lists)
	ListLists(ctx context.Context, request ListListsRequestObject) (ListListsResponseObject, error)
	// CreateList Create a list
	// (POST /api/v1/lists)
	CreateList(ctx context.Context, request CreateListRequestObject) (CreateListResponseObject, error)
	// DeleteList Delete a list
	// (DELETE /api/v1/lists/{listId})
	DeleteList(ctx context.Context, request DeleteListRequestObject) (DeleteListResponseObject, error)
	// GetList Get a list (owner view)
	// (GET /api/v1/lists/{listId})
	GetList(ctx context.Context, request GetListRequestObject) (GetListResponseObject, error)
	// UpdateList Update a list
	// (PATCH /api/v1/lists/{listId})
	UpdateList(ctx context.Context, request UpdateListRequestObject) (UpdateListResponseObject, error)
	// ListItems List items in a list
	// (GET /api/v1/lists/{listId}/items)
	ListItems(ctx context.Context, request ListItemsRequestObject) (ListItemsResponseObject, error)
	// CreateItem Add an item
	// (POST /api/v1/lists/{listId}/items)
	CreateItem(ctx context.Context, request CreateItemRequestObject) (CreateItemResponseObject, error)
	// GetCurrentUser Get the current owner/tenant
	// (GET /api/v1/me)
	GetCurrentUser(ctx context.Context, request GetCurrentUserRequestObject) (GetCurrentUserResponseObject, error)
	// ChangePassword Change the authenticated owner's password
	// (PUT /api/v1/me/password)
	ChangePassword(ctx context.Context, request ChangePasswordRequestObject) (ChangePasswordResponseObject, error)
	// GetTenantSettings Get the owner's tenant settings
	// (GET /api/v1/settings)
	GetTenantSettings(ctx context.Context, request GetTenantSettingsRequestObject) (GetTenantSettingsResponseObject, error)
	// UpdateTenantSettings Update the owner's tenant settings
	// (PATCH /api/v1/settings)
	UpdateTenantSettings(ctx context.Context, request UpdateTenantSettingsRequestObject) (UpdateTenantSettingsResponseObject, error)
	// GetHealthz Liveness probe
	// (GET /healthz)
	GetHealthz(ctx context.Context, request GetHealthzRequestObject) (GetHealthzResponseObject, error)
	// WithdrawContribution Withdraw a contribution (anonymous giver)
	// (DELETE /public/contributions/{contributionId})
	WithdrawContribution(ctx context.Context, request WithdrawContributionRequestObject) (WithdrawContributionResponseObject, error)
	// GetContribution Get a contribution and any pending match (anonymous giver)
	// (GET /public/contributions/{contributionId})
	GetContribution(ctx context.Context, request GetContributionRequestObject) (GetContributionResponseObject, error)
	// KeepByDecayToken Renew a stale reservation via its one-click decay token (anonymous)
	// (POST /public/decay-keep)
	KeepByDecayToken(ctx context.Context, request KeepByDecayTokenRequestObject) (KeepByDecayTokenResponseObject, error)
	// ReleaseByDecayToken Release a stale reservation via its one-click decay token (anonymous)
	// (POST /public/decay-release)
	ReleaseByDecayToken(ctx context.Context, request ReleaseByDecayTokenRequestObject) (ReleaseByDecayTokenResponseObject, error)
	// GetMatch Read a co-buying match's state (anonymous giver)
	// (GET /public/matches/{matchId})
	GetMatch(ctx context.Context, request GetMatchRequestObject) (GetMatchResponseObject, error)
	// ConfirmMatch Confirm or decline a proposed co-buying match
	// (POST /public/matches/{matchId}/confirm)
	ConfirmMatch(ctx context.Context, request ConfirmMatchRequestObject) (ConfirmMatchResponseObject, error)
	// ConfirmReservation Confirm an email_confirmed reservation via its emailed token (anonymous)
	// (POST /public/reservations/confirm)
	ConfirmReservation(ctx context.Context, request ConfirmReservationRequestObject) (ConfirmReservationResponseObject, error)
	// ReleaseReservation Release a reservation (anonymous giver)
	// (DELETE /public/reservations/{reservationId})
	ReleaseReservation(ctx context.Context, request ReleaseReservationRequestObject) (ReleaseReservationResponseObject, error)
	// GetPublicList View a shared list (anonymous)
	// (GET /public/{shareSlug})
	GetPublicList(ctx context.Context, request GetPublicListRequestObject) (GetPublicListResponseObject, error)
	// CreateContribution Pledge a share toward co-buying an item
	// (POST /public/{shareSlug}/items/{itemId}/contributions)
	CreateContribution(ctx context.Context, request CreateContributionRequestObject) (CreateContributionResponseObject, error)
	// CreateReservation Reserve an item (anonymous giver)
	// (POST /public/{shareSlug}/items/{itemId}/reservations)
	CreateReservation(ctx context.Context, request CreateReservationRequestObject) (CreateReservationResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

